exercises.solution:
class Path
{
public:
    explicit Path(int count) : points(new int[count]()), count(count) {}
    ~Path() { delete[] points; }

    // deep copy: our own array with the same values
    Path(const Path& other) : points(new int[other.count]()), count(other.count)
    {
        for (int i = 0; i < count; i++) points[i] = other.points[i];
    }

    Path& operator=(const Path& other)
    {
        if (this == &other) return *this;        // p = p: nothing to do
        int* fresh = new int[other.count]();     // make the new array first
        for (int i = 0; i < other.count; i++) fresh[i] = other.points[i];
        delete[] points;                         // then let go of the old one
        points = fresh;
        count = other.count;
        return *this;
    }

    void set(int i, int v) { if (i >= 0 && i < count) points[i] = v; }
    int get(int i) const { return (i >= 0 && i < count) ? points[i] : -1; }
    int size() const { return count; }
private:
    int* points;
    int count;
};

exercises.prompt:
An audio Channel must have exactly one owner. Add to class Channel:
- a deleted copy constructor and copy assignment;
- a move constructor Channel(Channel&& other) noexcept that takes other's id and sets other's id to -1;
- a move assignment operator that first closes the channel this object had (open-- if it owned one), then takes other's id and sets other's id to -1. Moving into itself must change nothing.
The open counter must stay correct: it counts channels that are really open.

exercises.starter:
#include <utility>
#include <type_traits>

class Channel
{
public:
    inline static int open = 0;   // how many audio channels are open right now

    explicit Channel(int id) : id(id) { open++; }
    ~Channel() { if (id >= 0) open--; }   // a moved-from channel (id -1) owns nothing

    // TODO: no copying; moving hands the channel over

    int getId() const { return id; }
    bool owns() const { return id >= 0; }
private:
    int id;
};

exercises.solution:
#include <utility>
#include <type_traits>

class Channel
{
public:
    inline static int open = 0;   // how many audio channels are open right now

    explicit Channel(int id) : id(id) { open++; }
    ~Channel() { if (id >= 0) open--; }   // a moved-from channel (id -1) owns nothing

    // one channel, one owner: no copies
    Channel(const Channel&) = delete;
    Channel& operator=(const Channel&) = delete;

    // moving takes the channel and leaves the old object empty
    Channel(Channel&& other) noexcept : id(other.id) { other.id = -1; }
    Channel& operator=(Channel&& other) noexcept
    {
        if (this != &other) {
            if (id >= 0) open--;      // close the channel we had
            id = other.id;
            other.id = -1;
        }
        return *this;
    }

    int getId() const { return id; }
    bool owns() const { return id >= 0; }
private:
    int id;
};

exercises.starter:
#include <string>

// Copying this crashes: two Scoreboards end up deleting the same array.
class Scoreboard
{
public:
    explicit Scoreboard(std::string title) : title(title), scores(new int[4]), n(0), cap(4) {}
    ~Scoreboard() { delete[] scores; }

    void add(int score)
    {
        if (n == cap) {
            int* bigger = new int[cap * 2];
            for (int i = 0; i < n; i++) bigger[i] = scores[i];
            delete[] scores;
            scores = bigger;
            cap *= 2;
        }
        scores[n++] = score;
    }
    int count() const { return n; }
    int best() const
    {
        int b = 0;
        for (int i = 0; i < n; i++) if (i == 0 || scores[i] > b) b = scores[i];
        return b;
    }
    std::string getTitle() const { return title; }
private:
    std::string title;
    int* scores;
    int n;
    int cap;
};

exercises.solution:
#include <string>
#include <vector>

// Rule of zero: the members manage themselves, so copying just works.
class Scoreboard
{
public:
    explicit Scoreboard(std::string title) : title(title) {}

    void add(int score) { scores.push_back(score); }
    int count() const { return scores.size(); }
    int best() const
    {
        int b = 0;
        for (size_t i = 0; i < scores.size(); i++)
            if (i == 0 || scores[i] > b) b = scores[i];
        return b;
    }
    std::string getTitle() const { return title; }
private:
    std::string title;
    std::vector<int> scores;
};
